if __name__ == "__main__":
    import argparse
    import sys
    from pathlib import Path

    # Configuration des arguments
    parser = argparse.ArgumentParser(description="Run WEST Magnetics Mapper")
    parser.add_argument('--shot', type=int, default=57420, help="Numéro du choc (ex: 57420)")
    parser.add_argument('--experiment', type=str, default="west", help="Nom de l'expérience (ex: west)")
    parser.add_argument('--config', type=str, help="Chemin vers le fichier config.toml")
    
    args = parser.parse_args()

    # Tentative de localisation automatique du config.toml
    config_path = None
    if args.config:
        config_path = Path(args.config)
    else:
        # Cherche dans le répertoire courant ou dans config/
        for p in [Path("config/config.toml"), Path("config.toml"), Path(__file__).parent / "config/config.toml"]:
            if p.exists():
                config_path = p
                break
    
    if not config_path or not config_path.exists():
        print(f"Erreur : Impossible de trouver le fichier de configuration config.toml.")
        print(f"Veuillez spécifier son chemin avec --config")
        sys.exit(1)

    print(f"--- LibTokaMap version: {libtokamap.__version__} ---")
    print(f"Config: {config_path}")
    print(f"Shot: {args.shot}, Experiment: {args.experiment}")
    print("------------------------------------------")

    try:
        # Initialisation du Mapper
        mapper = libtokamap.Mapper(str(config_path))
        
        # Exécution du mapping complet
        print(f"Démarrage du mapping pour l'IDS 'magnetics'...")
        map_all(mapper, args.experiment, args.shot)
        print("Mapping terminé avec succès.")
        
    except Exception as e:
        print(f"Une erreur est survenue lors de l'exécution : {e}")
        sys.exit(1)
